function buildMb04OrgGroup(side, section, sideName) {
  const s5 = `_${side}`;
  const sec = section;
  const holderHeading = `CH\u1EE6 T\xC0I KHO\u1EA2N ${sideName}`;
  const holder = `Ch\u1EE7 T\xE0i Kho\u1EA3n ${sideName === "TH\u1EE8 NH\u1EA4T" ? "Th\u1EE9 Nh\u1EA5t" : "Th\u1EE9 Hai"}`;
  const holderLower = `ch\u1EE7 t\xE0i kho\u1EA3n ${sideName === "TH\u1EE8 NH\u1EA4T" ? "th\u1EE9 nh\u1EA5t" : "th\u1EE9 hai"}`;
  return {
    name: `org_${side}`,
    contextHint: `Focus ONLY on Section "${sec}. TH\xD4NG TIN ${holderHeading}" of the joint-account form MB04 \u2014 the entire organization-info block of that ONE holder (organization identity, address, contact, business sector, SME extras, FATCA classification, relationship purpose). Do NOT read the OTHER holder's section, Section IV (joint services), Sections V\u2013IX (people lists, seals, handover, consent), or any other part of the form.`,
    aiFields: [
      // Thông tin cơ bản (10 fields)
      { key: `org_name_vi${s5}`, label: `${holder} \u2014 T\xEAn t\u1ED5 ch\u1EE9c (ti\u1EBFng Vi\u1EC7t)`, desc: `Full organization name in Vietnamese for ${holderLower}, labeled "T\xEAn ti\u1EBFng Vi\u1EC7t" under Section ${sec}.` },
      { key: `org_name_foreign${s5}`, label: `${holder} \u2014 T\xEAn t\u1ED5 ch\u1EE9c (ti\u1EBFng n\u01B0\u1EDBc ngo\xE0i)`, desc: `Full organization name in a foreign language for ${holderLower}, labeled "T\xEAn ti\u1EBFng n\u01B0\u1EDBc ngo\xE0i" under Section ${sec}. Null if blank.` },
      { key: `org_short_name${s5}`, label: `${holder} \u2014 T\xEAn vi\u1EBFt t\u1EAFt`, desc: `Organization abbreviation / short name for ${holderLower}, labeled "T\xEAn vi\u1EBFt t\u1EAFt". Null if blank.` },
      { key: `business_registration_no${s5}`, label: `${holder} \u2014 S\u1ED1 \u0110KDN/Q\u0110TL`, desc: `Enterprise / establishment-decision number for ${holderLower}, labeled "\u0110KDN/Q\u0110TL s\u1ED1" under Section ${sec}.` },
      { key: `establishment_date${s5}`, label: `${holder} \u2014 Ng\xE0y \u0110K / th\xE0nh l\u1EADp`, desc: `Establishment / registration date for ${holderLower}, labeled "Ng\xE0y \u0110K" under Section ${sec}. Return in DD/MM/YYYY format.` },
      { key: `registration_place${s5}`, label: `${holder} \u2014 N\u01A1i c\u1EA5p`, desc: `Issuing authority / place of registration for ${holderLower}, labeled "N\u01A1i c\u1EA5p" under Section ${sec}.` },
      { key: `establishment_country${s5}`, label: `${holder} \u2014 Qu\u1ED1c gia th\xE0nh l\u1EADp`, desc: `Country of establishment for ${holderLower}, labeled "Qu\u1ED1c gia" under Section ${sec}.` },
      { key: `tax_code${s5}`, label: `${holder} \u2014 M\xE3 s\u1ED1 thu\u1EBF`, desc: `Enterprise / tax code for ${holderLower}, labeled "M\xE3 s\u1ED1 thu\u1EBF" (MST) under Section ${sec}.` },
      { key: `org_identification_no${s5}`, label: `${holder} \u2014 S\u1ED1 \u0111\u1ECBnh danh c\u1EE7a t\u1ED5 ch\u1EE9c`, desc: `Organization identification number for ${holderLower}, labeled "S\u1ED1 \u0111\u1ECBnh danh" under Section ${sec}. Null if absent.` },
      { key: `state_budget_relation_code${s5}`, label: `${holder} \u2014 M\xE3 \u0110V c\xF3 QH v\u1EDBi NSNN`, desc: `Code of a unit having a relationship with the state budget for ${holderLower}, labeled "M\xE3 \u0111\u01A1n v\u1ECB c\xF3 QH v\u1EDBi NSNN" under Section ${sec}. Null if absent.` },
      // Địa chỉ & Liên hệ (8 fields)
      { key: `residency_status${s5}`, label: `${holder} \u2014 T\xECnh tr\u1EA1ng c\u01B0 tr\xFA`, type: "string[]", desc: `Residency-status checkbox under Section ${sec} for ${holderLower} \u2014 return a JSON array containing the ticked label ("C\u01B0 tr\xFA" or "Kh\xF4ng c\u01B0 tr\xFA"); [] if nothing ticked.` },
      { key: `head_office_address${s5}`, label: `${holder} \u2014 \u0110\u1ECBa ch\u1EC9 tr\u1EE5 s\u1EDF ch\xEDnh`, desc: `Head-office address for ${holderLower}, labeled "\u0110\u1ECBa ch\u1EC9 tr\u1EE5 s\u1EDF ch\xEDnh" under Section ${sec}. Often the boilerplate "Theo ghi nh\u1EADn t\u1EA1i \u0110KDN/Q\u0110TL n\xEAu tr\xEAn" \u2014 return as written.` },
      { key: `transaction_address_type${s5}`, label: `${holder} \u2014 Lo\u1EA1i \u0111\u1ECBa ch\u1EC9 giao d\u1ECBch`, type: "string[]", desc: `Transaction-address-type checkbox under Section ${sec} "\u0110\u1ECBa ch\u1EC9 giao d\u1ECBch" \u2014 return a JSON array containing the ticked label ("Gi\u1ED1ng \u0111\u1ECBa ch\u1EC9 tr\u1EE5 s\u1EDF ch\xEDnh" or "Kh\xE1c"); [] if nothing ticked.` },
      { key: `other_address_line${s5}`, label: `${holder} \u2014 \u0110\u1ECBa ch\u1EC9 kh\xE1c (to\xE0n d\xF2ng)`, desc: `The ENTIRE "Kh\xE1c" address as a single line written after "Kh\xE1c" under Section ${sec} for ${holderLower} (only when "Kh\xE1c" is ticked); null otherwise.` },
      { key: `other_address_street${s5}`, label: `${holder} \u2014 \u0110\u1ECBa ch\u1EC9 kh\xE1c \u2014 S\u1ED1 nh\xE0 / T\u1EA7ng / T\xF2a nh\xE0, t\xEAn \u0111\u01B0\u1EDDng`, desc: STREET_LEVEL_DESC },
      { key: `other_address_ward${s5}`, label: `${holder} \u2014 Ph\u01B0\u1EDDng/X\xE3 (\u0111\u1ECBa ch\u1EC9 kh\xE1c)`, desc: `Ward name written on the "Ph\u01B0\u1EDDng/x\xE3" line of the "Kh\xE1c" address under Section ${sec}; null when the "Kh\xE1c" option is not ticked or the line is blank.` },
      { key: `other_address_district${s5}`, label: `${holder} \u2014 Qu\u1EADn/Huy\u1EC7n (\u0111\u1ECBa ch\u1EC9 kh\xE1c)`, desc: `District written on the "Qu\u1EADn/Huy\u1EC7n" line of the "Kh\xE1c" address under Section ${sec}; null when the "Kh\xE1c" option is not ticked or the line is blank.` },
      { key: `other_address_province${s5}`, label: `${holder} \u2014 T\u1EC9nh/TP (\u0111\u1ECBa ch\u1EC9 kh\xE1c)`, desc: `Province / city written on the "T\u1EC9nh/Th\xE0nh ph\u1ED1" line of the "Kh\xE1c" address under Section ${sec}; null when the "Kh\xE1c" option is not ticked or the line is blank.` },
      { key: `phone${s5}`, label: `${holder} \u2014 S\u1ED1 \u0111i\u1EC7n tho\u1EA1i`, desc: `Organization phone number for ${holderLower}, labeled "\u0110i\u1EC7n tho\u1EA1i" under Section ${sec}.` },
      { key: `email${s5}`, label: `${holder} \u2014 Email`, desc: `Organization email used for VPBank notifications for ${holderLower}, labeled "Email" under Section ${sec}.` },
      // Lĩnh vực kinh doanh (2 fields)
      { key: `main_business_sector${s5}`, label: `${holder} \u2014 T\xEAn ng\xE0nh`, desc: `Main business sector name for ${holderLower}, labeled "T\xEAn ng\xE0nh" (L\u0129nh v\u1EF1c kinh doanh ch\xEDnh) under Section ${sec}.` },
      { key: `business_sector_code${s5}`, label: `${holder} \u2014 M\xE3 ng\xE0nh (c\u1EA5p 5)`, desc: `Business sector code (level 5) for ${holderLower}, labeled "M\xE3 ng\xE0nh (c\u1EA5p 5)" under Section ${sec}.` },
      // SME (5 fields)
      { key: `sme_micro_enterprise${s5}`, label: `${holder} \u2014 Quy m\xF4 doanh nghi\u1EC7p si\xEAu nh\u1ECF`, type: "string[]", desc: `Return a JSON array containing "Quy m\xF4 doanh nghi\u1EC7p si\xEAu nh\u1ECF v\xE0 \xE1p d\u1EE5ng ch\u1EBF \u0111\u1ED9 k\u1EBF to\xE1n \u0111\u01A1n gi\u1EA3n" when that checkbox is ticked under Section ${sec} for ${holderLower}; else null.` },
      { key: `sme_previous_year_revenue${s5}`, label: `${holder} \u2014 Doanh thu n\u0103m tr\u01B0\u1EDBc (t\u1EF7 \u0111\u1ED3ng)`, type: "string[]", desc: `Previous-year revenue band under Section ${sec} for ${holderLower} \u2014 return a JSON array containing the ticked band label (one of "<=3", "tr\xEAn 3-10", "tr\xEAn 10-20", "tr\xEAn 20-30", "tr\xEAn 30-50", "tr\xEAn 50-100", "tr\xEAn 100-200", "tr\xEAn 200-300", "tr\xEAn 300-400", "tr\xEAn 400"); [] if nothing ticked.` },
      { key: `sme_total_capital${s5}`, label: `${holder} \u2014 T\u1ED5ng ngu\u1ED3n v\u1ED1n (t\u1EF7 \u0111\u1ED3ng)`, type: "string[]", desc: `Total-capital band under Section ${sec} for ${holderLower} \u2014 return a JSON array containing the ticked band label (one of "<=3", "3-20", "20-50", "50-100", ">100"); [] if nothing ticked.` },
      { key: `sme_social_insurance_employees${s5}`, label: `${holder} \u2014 S\u1ED1 lao \u0111\u1ED9ng BHXH (ng\u01B0\u1EDDi)`, type: "string[]", desc: `Social-insurance-employees band under Section ${sec} for ${holderLower} \u2014 return a JSON array containing the ticked band label (one of "<=10", "10-50", "50-100", "100-200", ">200"); [] if nothing ticked.` },
      { key: `sme_woman_owned${s5}`, label: `${holder} \u2014 S\u1EDF h\u1EEFu b\u1EDFi ph\u1EE5 n\u1EEF`, type: "string[]", desc: `Woman-owned declaration under "KH c\xF3 \u0111\u01B0\u1EE3c s\u1EDF h\u1EEFu b\u1EDFi ph\u1EE5 n\u1EEF kh\xF4ng" under Section ${sec} for ${holderLower} \u2014 return a JSON array containing the ticked-option label; if a free-text answer is written, wrap it as a single-element array; [] if nothing ticked.` },
      // FATCA (2 fields)
      { key: `fatca_us_tax_code${s5}`, label: `${holder} \u2014 M\xE3 s\u1ED1 thu\u1EBF Hoa K\u1EF3`, desc: `US tax code for ${holderLower} \u2014 labeled "M\xE3 s\u1ED1 thu\u1EBF Hoa K\u1EF3 c\u1EE7a t\u1ED5 ch\u1EE9c" in the FATCA sub-block of Section ${sec}. Null if the organization is not a US-law entity.` },
      { key: `fatca_classification${s5}`, label: `${holder} \u2014 Ph\xE2n lo\u1EA1i FATCA`, type: "string[]", desc: `FATCA classification for ${holderLower} under Section ${sec} \u2014 return a JSON array of the ticked classification labels (e.g. "T\u1ED5 ch\u1EE9c phi t\xE0i ch\xEDnh ch\u1EE7 \u0111\u1ED9ng", "T\u1ED5 ch\u1EE9c phi t\xE0i ch\xEDnh b\u1ECB \u0111\u1ED9ng", "T\u1ED5 ch\u1EE9c t\xE0i ch\xEDnh, vui l\xF2ng cung c\u1EA5p th\xF4ng tin theo M\u1EABu bi\u1EC3u W-8BEN-E", "Kh\xF4ng thu\u1ED9c m\u1ED9t trong c\xE1c tr\u01B0\u1EDDng h\u1EE3p tr\xEAn \u0111\xE2y"). [] if nothing ticked.` },
      // Mục đích, bản chất mối quan hệ (2 fields — 6 OCR tick options collapsed to 1 array + 1 khác text)
      { key: `relationship_purposes${s5}`, label: `${holder} \u2014 M\u1EE5c \u0111\xEDch quan h\u1EC7 v\u1EDBi VPBank`, type: "string[]", desc: `Purpose-of-relationship checkboxes under Section ${sec} for ${holderLower} \u2014 return a JSON array of the ticked labels (from "S\u1EED d\u1EE5ng d\u1ECBch v\u1EE5 thu, chi h\u1ED9", "Thanh to\xE1n, chuy\u1EC3n ti\u1EC1n, kinh doanh trong n\u01B0\u1EDBc", "Thanh to\xE1n, chuy\u1EC3n ti\u1EC1n, kinh doanh qu\u1ED1c t\u1EBF", "Qu\u1EA3n l\xFD d\xF2ng ti\u1EC1n", "C\xE1c m\u1EE5c \u0111\xEDch kh\xE1c ph\u1EE5c v\u1EE5 cho ho\u1EA1t \u0111\u1ED9ng v\u1EADn h\xE0nh t\u1ED5 ch\u1EE9c", "Kh\xE1c"). [] if nothing ticked.` },
      { key: `relationship_purpose_other${s5}`, label: `${holder} \u2014 M\u1EE5c \u0111\xEDch kh\xE1c (n\xEAu r\xF5)`, desc: `Free-text detail written after "Kh\xE1c:" in the relationship-purpose block under Section ${sec} for ${holderLower}; null when the "Kh\xE1c" option is not ticked.` }
    ]
  };
}
var MB04_GROUP_ORG_CTK1 = buildMb04OrgGroup("ctk1", "I", "TH\u1EE8 NH\u1EA4T");
