var PDF_EXTS = [".pdf"];
var IMAGE_EXTS = [".png", ".jpg", ".jpeg", ".webp", ".gif"];
var EXCEL_EXTS = [".xlsx", ".xls", ".csv"];
var PDF_MIMES = ["application/pdf"];
var IMAGE_MIMES = ["image/png", "image/jpeg", "image/webp", "image/gif"];
var EXCEL_MIMES = [
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  "application/vnd.ms-excel",
  "text/csv",
  "application/csv"
];
function classifyFiles(files) {
  const out = { pdfs: [], images: [], excels: [], others: [] };
  for (const f5 of files) {
    const ext = getExtension(f5.name);
    const mime = (f5.mime || "").toLowerCase();
    if (PDF_EXTS.includes(ext) || PDF_MIMES.includes(mime)) {
      out.pdfs.push(f5);
    } else if (IMAGE_EXTS.includes(ext) || IMAGE_MIMES.some((m5) => mime.startsWith(m5))) {
      out.images.push(f5);
    } else if (EXCEL_EXTS.includes(ext) || EXCEL_MIMES.includes(mime)) {
      out.excels.push(f5);
    } else {
      out.others.push(f5);
    }
  }
  return out;
}

